/*Table structure for table `tblbooklibrary` */

DROP TABLE IF EXISTS `tblbooklibrary`;

CREATE TABLE `tblbooklibrary` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `CategoryID` int(11) NOT NULL,
  `BookName` varchar(255) DEFAULT NULL,
  `BookNameAr` varchar(255) DEFAULT NULL,
  `AuthorName` varchar(255) NOT NULL,
  `AuthorNameAr` varchar(255) NOT NULL,
  `AuditorName` varchar(255) NOT NULL,
  `AuditorNameAr` varchar(255) NOT NULL,
  `PublisherName` varchar(255) NOT NULL,
  `PublisherNameAr` varchar(255) NOT NULL,
  `EditionNumber` varchar(255) NOT NULL,
  `Active` tinyint(1) DEFAULT NULL,
  `ThumbnailImage` varchar(255) NOT NULL,
  `CreatedBy` int(11) DEFAULT NULL,
  `CreatedDateTime` datetime DEFAULT NULL,
  `ModifiedBy` int(11) DEFAULT NULL,
  `ModifiedDateTime` datetime DEFAULT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8;

