/*Table structure for table `tblcategory_log` */

DROP TABLE IF EXISTS `tblcategory_log`;

CREATE TABLE `tblcategory_log` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `LogTableID` int(11) NOT NULL,
  `Title` varchar(255) NOT NULL,
  `TitleAr` varchar(255) NOT NULL,
  `Active` tinyint(1) NOT NULL,
  `ThumbnailImage` varchar(255) NOT NULL,
  `Sequence` int(11) NOT NULL,
  `URLKeyword` varchar(255) NOT NULL,
  `MetaTitle` text NOT NULL,
  `MetaTitleAr` text NOT NULL,
  `MetaKeywords` longblob NOT NULL,
  `MetaKeywordsAr` longblob NOT NULL,
  `MetaDescription` longblob NOT NULL,
  `MetaDescriptionAr` longblob NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `CreatedDateTime` datetime NOT NULL,
  `ModifiedBy` int(11) NOT NULL,
  `ModifiedDateTime` datetime NOT NULL,
  `Action` tinyint(4) NOT NULL COMMENT '1=insert,2=update,3=delete',
  `ActionBY` int(11) NOT NULL,
  `DateTime` datetime NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=latin1;

