/*Table structure for table `tblcoupon` */

DROP TABLE IF EXISTS `tblcoupon`;

CREATE TABLE `tblcoupon` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `StoreID` int(11) DEFAULT NULL,
  `CouponName` varchar(255) DEFAULT NULL,
  `url` text DEFAULT NULL,
  `description` blob DEFAULT NULL,
  `couponClassification` blob DEFAULT NULL,
  `couponCode` blob DEFAULT NULL,
  `H1` varchar(255) DEFAULT NULL,
  `H2` varchar(255) DEFAULT NULL,
  `webUrl` text DEFAULT NULL,
  `trackingLink` blob DEFAULT NULL,
  `sitewide` blob DEFAULT NULL,
  `logo` text DEFAULT NULL,
  `ShowHome` text DEFAULT NULL,
  `landingLink` blob DEFAULT NULL,
  `impression` varchar(255) DEFAULT NULL,
  `Active` tinyint(1) DEFAULT NULL COMMENT '1=enable , 2=disable , 0=delete',
  `discount` varchar(255) DEFAULT '15%',
  `CategoryID` varchar(255) DEFAULT NULL,
  `network_id` int(11) DEFAULT NULL,
  `networkID` text DEFAULT NULL,
  `startDate` date DEFAULT NULL,
  `endDate` date DEFAULT NULL,
  `featured` smallint(1) DEFAULT 0,
  `CouponTypeID` varchar(255) DEFAULT NULL,
  `CouponTagID` int(11) DEFAULT NULL,
  `upVotes` int(11) DEFAULT NULL,
  `downVotes` int(11) DEFAULT NULL,
  `Sequence` int(11) DEFAULT NULL,
  `CreatedAt` int(11) DEFAULT NULL,
  `CreatedBy` int(11) DEFAULT NULL,
  `CreatedDateTime` datetime DEFAULT NULL,
  `ModifiedBy` int(11) DEFAULT NULL,
  `ModifiedDateTime` datetime DEFAULT NULL,
  `CategoryIDForSavePurpose` varchar(255) DEFAULT NULL,
  `URLKeyword` text DEFAULT NULL,
  `MetaTitle` text DEFAULT NULL,
  `MetaKeywords` text DEFAULT NULL,
  `MetaDescription` text DEFAULT NULL,
  `MetaOthers` text DEFAULT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8;

/*Data for the table `tblcoupon` */

