/*Table structure for table `tblcourses` */

DROP TABLE IF EXISTS `tblcourses`;

CREATE TABLE `tblcourses` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `Title` varchar(255) DEFAULT NULL,
  `TitleAr` blob DEFAULT NULL,
  `BriefDescription` text NOT NULL,
  `BriefDescriptionAr` blob NOT NULL,
  `Description` blob NOT NULL,
  `DescriptionAr` blob NOT NULL,
  `CategoryID` int(11) NOT NULL,
  `PassPercentage` int(11) NOT NULL,
  `Active` tinyint(1) DEFAULT NULL,
  `ShowHome` varchar(255) CHARACTER SET latin1 DEFAULT NULL,
  `URLKeyword` varchar(255) NOT NULL,
  `MetaTitle` text NOT NULL,
  `MetaTitleAr` text NOT NULL,
  `MetaKeywords` longblob NOT NULL,
  `MetaKeywordsAr` longblob NOT NULL,
  `MetaDescription` longblob NOT NULL,
  `MetaDescriptionAr` longblob NOT NULL,
  `MetaOthers` longblob NOT NULL,
  `MetaOthersAr` longtext NOT NULL,
  `CreatedBy` int(11) DEFAULT NULL,
  `CreatedDateTime` datetime DEFAULT NULL,
  `ModifiedBy` int(11) DEFAULT NULL,
  `ModifiedDateTime` datetime DEFAULT NULL,
  `Sequence` int(11) NOT NULL,
  `BannerImage` varchar(255) NOT NULL,
  `ThumbnailImage` varchar(255) NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;

