/*Table structure for table `tblnewslettercampaigns` */

DROP TABLE IF EXISTS `tblnewslettercampaigns`;

CREATE TABLE `tblnewslettercampaigns` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `Title` varchar(255) NOT NULL,
  `ContactCategoryID` int(11) NOT NULL,
  `NewsLetterID` int(11) NOT NULL,
  `Subject` text NOT NULL,
  `CampaignStartDate` date NOT NULL,
  `ExceptionDays` varchar(255) NOT NULL,
  `FromTime` varchar(255) NOT NULL,
  `ToTime` varchar(255) NOT NULL,
  `EveryHourEmail` tinyint(1) NOT NULL,
  `ReplyToEmail` varchar(255) NOT NULL,
  `SenderName` varchar(255) NOT NULL,
  `Status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 for open, 1 for close',
  `TotalContact` int(11) NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `CreatedDateTime` datetime NOT NULL,
  `ModifiedBy` int(11) NOT NULL,
  `ModifiedDateTime` datetime NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;

