/*Table structure for table `tblpublicationstatus_log` */

DROP TABLE IF EXISTS `tblpublicationstatus_log`;

CREATE TABLE `tblpublicationstatus_log` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `LogTableID` int(11) NOT NULL,
  `Title` varchar(255) NOT NULL,
  `TitleAr` varchar(255) NOT NULL,
  `Active` tinyint(1) NOT NULL,
  `Sequence` int(11) NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `CreatedDateTime` datetime NOT NULL,
  `ModifiedBy` int(11) NOT NULL,
  `ModifiedDateTime` datetime NOT NULL,
  `Action` tinyint(4) NOT NULL COMMENT '1=insert,2=update,3=delete',
  `ActionBY` int(11) NOT NULL,
  `DateTime` datetime NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;

