/*Table structure for table `tblstore` */

DROP TABLE IF EXISTS `tblstore`;

CREATE TABLE `tblstore` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `logo` text DEFAULT NULL,
  `url` text DEFAULT NULL,
  `description` text NOT NULL,
  `domain` varchar(255) NOT NULL,
  `webUrl` text DEFAULT NULL,
  `trackingUrl` text DEFAULT NULL,
  `disableUrl` text DEFAULT NULL,
  `discount` varchar(255) NOT NULL,
  `fbUrl` text DEFAULT NULL,
  `about` text NOT NULL,
  `ShowHome` smallint(1) DEFAULT 0,
  `rating` text DEFAULT NULL,
  `storeAdd` text DEFAULT NULL,
  `votes` int(11) DEFAULT NULL,
  `impressionCode` text DEFAULT NULL,
  `SimilarStoreID` varchar(255) DEFAULT NULL,
  `storeIDActiveNetwork` int(11) DEFAULT NULL,
  `CountryID` int(11) NOT NULL,
  `featured` smallint(6) NOT NULL,
  `H1` varchar(255) DEFAULT NULL,
  `H2` varchar(255) DEFAULT NULL,
  `CategoryID` varchar(255) NOT NULL,
  `NetworkID` int(11) NOT NULL,
  `Active` tinyint(1) NOT NULL COMMENT '1=enable , 2=disable , 0=delete',
  `Sequence` int(11) NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `storeDate` date NOT NULL,
  `CreatedDateTime` datetime NOT NULL,
  `ModifiedBy` int(11) NOT NULL,
  `ModifiedDateTime` datetime NOT NULL,
  `URLKeyword` text DEFAULT NULL,
  `MetaTitle` text DEFAULT NULL,
  `MetaKeywords` text DEFAULT NULL,
  `MetaDescription` text DEFAULT NULL,
  `MetaOthers` text DEFAULT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=latin1;

