/*Table structure for table `tblstore_log` */

DROP TABLE IF EXISTS `tblstore_log`;

CREATE TABLE `tblstore_log` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `Title` varchar(255) NOT NULL,
  `logo` text NOT NULL,
  `url` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `domain` varchar(255) DEFAULT NULL,
  `webUrl` text NOT NULL,
  `trackingUrl` text NOT NULL,
  `discount` double NOT NULL,
  `fbUrl` text NOT NULL,
  `about` text NOT NULL,
  `ShowHome` smallint(1) NOT NULL DEFAULT 0,
  `rating` text NOT NULL,
  `storeAdd` text NOT NULL,
  `votes` int(11) NOT NULL,
  `featured` smallint(1) NOT NULL,
  `impressionCode` int(11) DEFAULT NULL,
  `storeIDActiveNetwork` int(11) NOT NULL,
  `CountryID` int(11) NOT NULL,
  `CategoryID` int(11) NOT NULL,
  `NetworkID` int(11) NOT NULL,
  `Active` tinyint(1) NOT NULL,
  `Sequence` int(11) NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `storeDate` date DEFAULT NULL,
  `CreatedDateTime` datetime NOT NULL,
  `ModifiedBy` int(11) NOT NULL,
  `ModifiedDateTime` datetime NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

