/*Table structure for table `tblsystemusers` */

DROP TABLE IF EXISTS `tblsystemusers`;

CREATE TABLE `tblsystemusers` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `RoleID` int(11) DEFAULT NULL,
  `UserName` varchar(255) DEFAULT NULL,
  `Password` varchar(255) DEFAULT NULL,
  `Email` varchar(255) DEFAULT NULL,
  `EmpNo` varchar(255) DEFAULT NULL,
  `MobileNo` varchar(255) DEFAULT NULL,
  `DepartmentID` int(11) DEFAULT NULL,
  `DesignationID` int(11) DEFAULT NULL,
  `LastLoginIP` varchar(255) DEFAULT NULL,
  `LastloginDateTime` datetime DEFAULT NULL,
  `Active` tinyint(4) DEFAULT NULL,
  `PasswordActive` tinyint(1) NOT NULL,
  `InvalidLoginAttempt` int(1) NOT NULL,
  `Online` int(11) NOT NULL,
  `ActiveLogin` int(11) NOT NULL,
  `LastActiveTime` int(11) NOT NULL,
  `FullName` varchar(255) DEFAULT NULL,
  `FullNameAr` varchar(255) DEFAULT NULL,
  `AllowToCreateEmp` tinyint(1) DEFAULT NULL,
  `EventID` varchar(255) NOT NULL,
  `PerPageRecord` int(11) NOT NULL,
  `CreatedBy` int(11) DEFAULT NULL,
  `CreatedDateTime` datetime DEFAULT NULL,
  `ModifiedBy` int(11) DEFAULT NULL,
  `ModifiedDateTime` datetime DEFAULT NULL,
  `UserAgent` varchar(255) NOT NULL,
  `SessionID` varchar(255) NOT NULL,
  `BlockTime` datetime NOT NULL,
  `BlockBy` int(11) NOT NULL COMMENT '0=admin, 1=user',
  PRIMARY KEY (`TableID`),
  KEY `connected with role` (`RoleID`),
  KEY `connected with department` (`DepartmentID`),
  KEY `connected with designation` (`DesignationID`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=latin1;

