/*Table structure for table `tblsystemusers_login_log` */

DROP TABLE IF EXISTS `tblsystemusers_login_log`;

CREATE TABLE `tblsystemusers_login_log` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `UserID` int(11) NOT NULL,
  `UserName` varchar(255) NOT NULL,
  `UserIP` varchar(255) NOT NULL,
  `DateTime` datetime NOT NULL,
  `Status` int(11) NOT NULL COMMENT '0=fail , 1=success',
  `Reason` int(11) NOT NULL COMMENT '1=username,pswd error, 2=user blocked	',
  `Type` int(11) NOT NULL COMMENT '1=login, 0=logout',
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=686 DEFAULT CHARSET=latin1;

