  `LogTableID` int(11) NOT NULL,
  `SublinkID` int(11) DEFAULT NULL,
  `ViewPermissions` tinyint(1) DEFAULT NULL,
  `AddPermissions` tinyint(1) DEFAULT NULL,
  `EditPermissions` tinyint(1) DEFAULT NULL,
  `DeletePermissions` tinyint(1) DEFAULT NULL,
  `UserID` int(11) DEFAULT NULL,
  `CreatedBy` int(11) DEFAULT NULL,
  `CreatedDateTime` datetime DEFAULT NULL,
  `ModifiedBy` int(11) DEFAULT NULL,
  `ModifiedDateTime` datetime DEFAULT NULL,
  `Action` tinyint(4) NOT NULL COMMENT '1=insert,2=update,3=delete',
  `ActionBY` int(11) NOT NULL,
  `DateTime` datetime NOT NULL,
  PRIMARY KEY (`TableID`),
  KEY `forign key of sublink table` (`SublinkID`),
  KEY `forign key for system user id` (`UserID`),
  KEY `tbluserpermissions_log_ibfk_1` (`CreatedBy`)
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=latin1;

