/*Table structure for table `tbluserregistration` */

DROP TABLE IF EXISTS `tbluserregistration`;

CREATE TABLE `tbluserregistration` (
  `TableID` int(11) NOT NULL AUTO_INCREMENT,
  `FullName` varchar(255) NOT NULL,
  `Gender` tinyint(10) NOT NULL COMMENT '1=male,2=female',
  `DOB` date NOT NULL,
  `NationalityID` int(11) NOT NULL,
  `Country_ResidenceID` int(11) NOT NULL,
  `Mobile` varchar(100) NOT NULL,
  `Email` varchar(255) NOT NULL,
  `Password` varchar(255) NOT NULL,
  `Status` tinyint(4) NOT NULL,
  `RegID` varchar(255) NOT NULL,
  `SessionID` varchar(255) NOT NULL,
  `CreatedBy` int(11) NOT NULL,
  `CreationDate` datetime NOT NULL,
  PRIMARY KEY (`TableID`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=latin1;

